mapper.select:
SELECT inv.item_id itemId, inv.department_id departmentId, i.item_code itemCode, i.item_name itemName, i.spec, i.unit, inv.current_qty currentQty, i.active, inv.updated_at updatedAt FROM inventory inv JOIN item i ON i.item_id = inv.item_id
AND (i.item_code LIKE CONCAT('%',#{keyword},'%') OR i.item_name LIKE CONCAT('%',#{keyword},'%')) AND inv.current_qty <= #{maxQty}
ORDER BY i.item_code, inv.department_id

SELECT mr.request_id issueId, mr.request_id requestId, mr.item_id itemId, i.item_code itemCode, i.item_name itemName, mr.request_qty releaseQty, mr.issued_qty issueQty, mr.status, mr.created_at requestedAt, mr.issued_at issuedAt, COALESCE((SELECT inv.current_qty FROM inventory inv WHERE inv.item_id=mr.item_id AND inv.department_id=mr.department_id),0) availableQty, mr.required_date scheduleDate, mr.request_qty requiredQty FROM material_request mr JOIN item i ON i.item_id=mr.item_id
AND DATE(mr.created_at)>=#{fromDate} AND DATE(mr.created_at)<=#{toDate} AND i.item_code=#{itemCode} AND mr.status=#{status}
ORDER BY mr.required_date, mr.request_id DESC

SELECT , p.created_at orderDate
FROM procurement p JOIN item i ON i.item_id=p.item_id
LEFT JOIN vendor v ON v.vendor_id=p.selected_vendor_id
LEFT JOIN vendor_quote q ON q.quote_id=(SELECT MAX(vq.quote_id) FROM vendor_quote vq WHERE vq.procurement_id=p.procurement_id)

	AND DATE(p.created_at)>=#{fromDate}
	AND DATE(p.created_at)<=#{toDate}
	AND p.status=#{status}
	AND (CAST(p.procurement_id AS CHAR) LIKE CONCAT('%',#{keyword},'%') OR i.item_name LIKE CONCAT('%',#{keyword},'%') OR v.vendor_name LIKE CONCAT('%',#{keyword},'%'))

ORDER BY p.created_at DESC

mapper.update:
UPDATE inventory inv
JOIN item i ON i.item_id=inv.item_id AND i.active=1
SET inv.current_qty=inv.current_qty-#{qty}, inv.updated_at=NOW()
WHERE inv.department_id=#{departmentId} AND inv.item_id=#{itemId}
  AND #{qty} > 0 AND inv.current_qty >= #{qty}
